def common_verify_mandatory_configuration(bts_id=0, du_id=0):
    additional_params = get_builtin_value("MANDATORY_ADDITIONAL_SCF_PARAMS")
    current_build = SwVersionFactory.create_sw_version(GnbDuOperations().get_bts_sw_version(bts_id=bts_id,
                                                                                            du_id=du_id))
    params = {}
    if additional_params is not None and "dict" in str(type(additional_params)):
        params.update(additional_params)
    params.update(common_params)
    for raw_build in mandatory_params:
        build = SwVersionFactory.create_sw_version(raw_build)
        if type(current_build) is type(build) and current_build >= build:
            params.update(mandatory_params[raw_build])

    VerifyMandatoryConfiguration().verify_mandatory_parameters_and_change_mismatch(params=params, bts_id=bts_id,
                                                                                   du_id=du_id)


def common_verify_mandatory_configuration_for_all_gnbs():
    bts_devices = get_all_bts_and_du_ids(bts_type="GNB")
    for device in bts_devices:
        common_verify_mandatory_configuration(bts_id=device["bts_id"], du_id=device["du_id"])


class VerifyMandatoryConfiguration(GenericBts):
    MAIL_SUBJECT = '[Action Required] Please adapt your SCF'
    MAIL_BODY = "The following parameters have been automatically changed. Please adjust your current SCF " \
                "values to avoid receiving similar emails in the future:<br><br><pre>{}</pre>"

    def __init__(self, bts_type='GNB'):
        super(VerifyMandatoryConfiguration, self).__init__(bts_type)
        self._email_delta_details = []

    def verify_mandatory_parameters_and_change_mismatch_multi_bts(self, params=None, allow_change_param=True,
                                                                  allow_reset=True, device_kwargs=None):
        bts_devices = get_all_bts_and_du_ids(bts_type=self.bts_type)
        for device in bts_devices:
            device_name = self.ssh_alias.format(device["bts_id"], device["du_id"])
            if device_kwargs is not None and device_name in device_kwargs.keys():
                self.verify_mandatory_parameters_and_change_mismatch(bts_id=device["bts_id"],
                                                                     du_id=device["du_id"],
                                                                     **device_kwargs[device_name])
            else:
                self.verify_mandatory_parameters_and_change_mismatch(params=params, allow_reset=allow_reset,
                                                                     allow_change_param=allow_change_param,
                                                                     bts_id=device["bts_id"],
                                                                     du_id=device["du_id"])

    @login_logout
    def check_if_param_is_possible_to_change(self, param_name, param_dict, xml_scf, string_scf, delta_id,
                                             bts_id=0, du_id=0):
        _pattern = re.sub(r'\$$', '', param_dict['distName'].pattern)
        _dist_name_regex = re.compile(r'distName="({})"'.format(_pattern))
        dist_names = _dist_name_regex.findall(string_scf)
        if len(dist_names) == 0:
            if not param_dict.get('ignore_if_not_exists'):
                log_warn_to_console("Unable to find : {}, create needed object in your scf!".format(param_name))
            return None
        if "related_params" in param_dict.keys():
            for related_param in param_dict["related_params"].keys():
                self.add_param_to_delta(param_name=related_param, xml_scf=xml_scf, string_scf=string_scf,
                                        delta_id=delta_id, bts_id=bts_id, du_id=du_id,
                                        param_dict=param_dict["related_params"][related_param])
        for dist_name in dist_names:
            msg = "Adding '{}={}' under [{}]".format(param_name, param_dict["value"], dist_name)
            self._print_debug_log(msg)
            self._email_delta_details.append([dist_name, param_name, '', param_dict["value"]])
            self.admin.append_parameter_update_to_delta(dist_name=dist_name, parameter=param_name,
                                                        value=param_dict["value"], delta_id=delta_id)
        delta = self.admin.get_delta(delta_id=delta_id)
        try:
            self._try_to_perform_delta_recommissioning(delta=delta, activate=False, bts_id=bts_id, du_id=du_id)
            return delta
        except AdminApiProcedureFailureException:
            log_warn_to_console("Unable to find: {}, please check your scf".format(param_name))
            return None

    def add_param_to_delta(self, param_name, param_dict, xml_scf, string_scf, delta_id, bts_id=0, du_id=0):
        found_params = xml_scf.findall(".//*[@name='{}']".format(param_name))
        if len(found_params) == 0:
            return self.check_if_param_is_possible_to_change(param_name, param_dict, xml_scf, string_scf, delta_id,
                                                             bts_id=bts_id, du_id=du_id)
        for found_param in found_params:
            dist_name = found_param.getparent().attrib["distName"]
            param_dist_name = param_dict.get("distName")
            if param_dist_name and not param_dist_name.search(dist_name):
                self._print_debug_log("Ignoring the changing '{}' because the dist_name [{}] does not match".
                                      format(param_name, dist_name))
                continue
            param_value = found_param.text
            wanted_value = param_dict["value"]() if callable(param_dict["value"]) else param_dict["value"]
            validation_values = param_dict.get("validation_values")
            _correct_msg = "'{}' [{}] has correct value '{}'".format(param_name, dist_name, param_value)
            _incorrect_msg = "Changing '{}' [{}] from [{}] to [{}]".format(param_name, dist_name, param_value,
                                                                           wanted_value)
            if validation_values:
                if callable(validation_values):
                    wanted_value_to_compare = self._try_to_convert_to_int(wanted_value)
                    param_value_to_compare = int(param_value) if isinstance(wanted_value_to_compare, int) \
                        else str(param_value)
                    if validation_values(param_value_to_compare, wanted_value_to_compare):
                        self._print_debug_log(_correct_msg)
                        continue
                else:
                    if param_value in validation_values:
                        self._print_debug_log(_correct_msg)
                        continue
            if str(param_value).lower() != str(wanted_value).lower():
                str_wanted_walue = str(wanted_value).lower() if isinstance(wanted_value, bool) else str(wanted_value)
                self._email_delta_details.append([dist_name, param_name, param_value, str_wanted_walue])
                self._print_debug_log(_incorrect_msg)
                self.admin.append_parameter_update_to_delta(dist_name=dist_name, parameter=param_name,
                                                            value=wanted_value, delta_id=delta_id)
                if "related_params" in param_dict.keys():
                    for related_param in param_dict["related_params"]:
                        self.add_param_to_delta(param_name=related_param, xml_scf=xml_scf, string_scf=string_scf,
                                                delta_id=delta_id, bts_id=bts_id, du_id=du_id,
                                                param_dict=param_dict["related_params"][related_param])
            else:
                self._print_debug_log(_correct_msg)
        return self.admin.get_delta(delta_id=delta_id)

    @login_logout
    def verify_mandatory_parameters_and_change_mismatch(self, params, allow_change_param=True, allow_reset=True,
                                                        bts_id=0, du_id=0):
        """
        Verify if given params have same values on BTS, if not change value to provided
        :param params: dict with params to be verified, should be passed as:
        {"value": value that should be on BTS, if mismatch, this value will be set,
         "distName": distName of object, that contain the param
         "validation_values": list/set of values that are allowed for this param
         "related_params": dict with params same as above, that should be changed with given param}, example:
         {"detUnstEcpriLnkFecCcwInvThr": {"value": 100000, "distname": "TRBLCADM", "release": "SBTS23R2",
         "validation_values": range(1000, 100000000)}
        :param allow_change_param: if True, then if param mismatch with given value, change the value
        :param allow_reset: if True, if reset is needed to change param, then will be performed
        :param bts_id: BTS ID from init
        :param du_id: DU ID from init
        """
        scf = self.admin.get_scf(connection=self.rest_alias.format(bts_id, du_id), with_auto_configured_parameters=True)
        root = etree.XML(scf.encode())
        final_delta = []
        for param in params.keys():
            delta_id = str(param) + str(time.time()).split(".")[0]
            self.admin.create_delta(delta_id=delta_id)
            delta = self.add_param_to_delta(param_name=param, param_dict=params[param], delta_id=delta_id, xml_scf=root,
                                            string_scf=scf, bts_id=bts_id, du_id=du_id)

            if delta is not None and delta != "[]":
                delta = json.loads(delta)
                final_delta.extend(delta)
            else:
                self.admin.remove_delta(delta_id=delta_id)

        if allow_change_param is False or not final_delta:
            return
        params_tb_change = [params["parameterName"] for delta in final_delta for params in delta["parameters"]]
        try:
            delta_results = self._try_to_perform_delta_recommissioning(delta=json.dumps(final_delta, indent=2),
                                                                       activate=False, bts_id=bts_id, du_id=du_id)
        except AdminApiProcedureFailureException as e:
            log_warn_to_console("Failed to change parameters: {}, due to: \n {}".format(", ".join(params_tb_change), e))
            return
        reset_coverage = delta_results["commissioningResult"]["resultNode"]["parameters"]["resetCoverage"]
        if reset_coverage[0] != "None" and allow_reset:
            log_info_to_console("Reset will be performed for {}".format(", ".join(reset_coverage)))
        elif reset_coverage[0] != "None" and not allow_reset:
            return

        log_warn_to_console("{} params will be changed, please update your SCF".
                            format(", ".join([j["parameterName"] for i in final_delta for j in i["parameters"]])))

        if get_builtin_value('SEND_CONFIGURATION_VALIDATION_EMAIL'):
            mail_body = tabulate(tabular_data=self._email_delta_details,
                                 headers=['Dist Name', 'Param Name', 'Current Value', 'New Value'],
                                 tablefmt="grid")
            send_email_with_default_template(subject=self.MAIL_SUBJECT,
                                             additional_info=self.MAIL_BODY.format(mail_body),
                                             add_team_email=False)

        self._try_to_perform_delta_recommissioning(delta=json.dumps(final_delta, indent=2), activate=True,
                                                   bts_id=bts_id, du_id=du_id)

    @login_logout
    def _try_to_perform_delta_recommissioning(self, delta, activate=False, bts_id=0, du_id=0):
        return self.admin.perform_delta_recommissioning(delta, connection=self.rest_alias.format(bts_id, du_id),
                                                        should_activate=activate)

    @staticmethod
    def _print_debug_log(msg):
        logging.debug("[PARAMS VALIDATOR] {}".format(msg))

    @staticmethod
    def _try_to_convert_to_int(value):
        try:
            return int(value)
        except ValueError:
            return value
